package db

// Hand-written, not generated by sqlc: sqlc keeps each query's SQL in an
// unexported constant, and the report catalog (GET /api/reports/queries)
// shows exactly that text, so it can never drift from what the API runs.

var queryText = map[string]string{
	"SearchBooks":             searchBooks,
	"GetBookByID":             getBookByID,
	"ListShelfBooks":          listShelfBooks,
	"TopRatedBooks":           topRatedBooks,
	"RatingSummaryByCategory": ratingSummaryByCategory,
	"RatingSummaryByAuthor":   ratingSummaryByAuthor,
	"PopularBooks":            popularBooks,
	"RecommendedBooks":        recommendedBooks,
	"UserReadingStats":        userReadingStats,
	"ReadingReportSummary":    readingReportSummary,
	"FavoriteCategories":      favoriteCategories,
	"RecentReadingActivity":   recentReadingActivity,
	"AuthorRankings":          authorRankings,
	"CategoryRankings":        categoryRankings,
	"ReviewActivity":          reviewActivity,
	"GetRatingDistribution":   getRatingDistribution,
}

// QueryText returns the SQL of a named query in database/queries/.
func QueryText(name string) (string, bool) {
	sql, ok := queryText[name]
	return sql, ok
}
